\set ON_ERROR_STOP on
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE EXTENSION IF NOT EXISTS citext;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE TYPE user_role AS ENUM ('customer','staff','admin'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE vehicle_status AS ENUM ('available','maintenance','retired','rented'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE fuel_type AS ENUM ('petrol','diesel','electric','hybrid','cng'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE transmission_type AS ENUM ('manual','automatic'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE booking_status AS ENUM ('pending','confirmed','active','completed','cancelled'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE payment_method AS ENUM ('card','upi','netbanking','cash'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE payment_status AS ENUM ('paid','refunded','failed'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE users(user_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, full_name VARCHAR(100) NOT NULL, email CITEXT NOT NULL UNIQUE, phone VARCHAR(15) NOT NULL CHECK(phone ~ '^[0-9+ -]{10,15}$'), password_hash TEXT NOT NULL, role user_role NOT NULL DEFAULT 'customer', is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE customer_profiles(user_id BIGINT PRIMARY KEY REFERENCES users ON DELETE CASCADE, licence_no VARCHAR(30) NOT NULL UNIQUE, licence_expiry DATE NOT NULL, date_of_birth DATE NOT NULL, address TEXT);
CREATE TABLE branches(branch_id INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,city VARCHAR(60) NOT NULL,address TEXT NOT NULL,phone VARCHAR(15));
CREATE TABLE vehicle_categories(category_id INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name VARCHAR(40) NOT NULL UNIQUE,base_daily_rate NUMERIC(10,2) NOT NULL CHECK(base_daily_rate>0),seats SMALLINT NOT NULL CHECK(seats BETWEEN 1 AND 15));
CREATE TABLE vehicles(vehicle_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,reg_number VARCHAR(15) NOT NULL UNIQUE,category_id INT NOT NULL REFERENCES vehicle_categories,branch_id INT NOT NULL REFERENCES branches,make VARCHAR(40) NOT NULL,model VARCHAR(40) NOT NULL,manufacture_year SMALLINT NOT NULL CHECK(manufacture_year BETWEEN 2000 AND 2100),fuel fuel_type NOT NULL,transmission transmission_type NOT NULL,odometer_km INT NOT NULL DEFAULT 0 CHECK(odometer_km>=0),status vehicle_status NOT NULL DEFAULT 'available',image_url TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE extras(extra_id INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name VARCHAR(50) NOT NULL UNIQUE,price_per_day NUMERIC(8,2) NOT NULL CHECK(price_per_day>=0));
CREATE TABLE maintenance_records(maintenance_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,vehicle_id BIGINT NOT NULL REFERENCES vehicles,description TEXT NOT NULL,start_date DATE NOT NULL,end_date DATE,cost NUMERIC(10,2) CHECK(cost>=0),CHECK(end_date IS NULL OR end_date>=start_date));
CREATE TABLE bookings(booking_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,customer_id BIGINT NOT NULL REFERENCES users,vehicle_id BIGINT NOT NULL REFERENCES vehicles,pickup_branch_id INT NOT NULL REFERENCES branches,drop_branch_id INT NOT NULL REFERENCES branches,period TSTZRANGE NOT NULL,daily_rate_snapshot NUMERIC(10,2) NOT NULL CHECK(daily_rate_snapshot>0),total_amount NUMERIC(10,2) NOT NULL CHECK(total_amount>=0),status booking_status NOT NULL DEFAULT 'pending',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(NOT lower_inf(period) AND NOT upper_inf(period) AND lower(period)<upper(period)),CONSTRAINT no_double_booking EXCLUDE USING gist(vehicle_id WITH =,period WITH &&) WHERE(status IN ('pending','confirmed','active')));
CREATE TABLE booking_extras(booking_id BIGINT NOT NULL REFERENCES bookings ON DELETE CASCADE,extra_id INT NOT NULL REFERENCES extras,quantity SMALLINT NOT NULL DEFAULT 1 CHECK(quantity BETWEEN 1 AND 5),price_per_day_snapshot NUMERIC(8,2) NOT NULL CHECK(price_per_day_snapshot>=0),PRIMARY KEY(booking_id,extra_id));
CREATE TABLE payments(payment_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,booking_id BIGINT NOT NULL REFERENCES bookings,amount NUMERIC(10,2) NOT NULL CHECK(amount>0),method payment_method NOT NULL,status payment_status NOT NULL,transaction_ref VARCHAR(60) UNIQUE,paid_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE rentals(rental_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,booking_id BIGINT NOT NULL UNIQUE REFERENCES bookings,handed_out_by BIGINT NOT NULL REFERENCES users,received_by BIGINT REFERENCES users,pickup_at TIMESTAMPTZ NOT NULL DEFAULT now(),return_at TIMESTAMPTZ,odometer_out INT NOT NULL CHECK(odometer_out>=0),odometer_in INT,CHECK(odometer_in IS NULL OR odometer_in>=odometer_out),CHECK(return_at IS NULL OR return_at>=pickup_at));
CREATE TABLE damage_reports(report_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,rental_id BIGINT NOT NULL REFERENCES rentals ON DELETE CASCADE,description TEXT NOT NULL,amount NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK(amount>=0),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE reviews(review_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,booking_id BIGINT NOT NULL UNIQUE REFERENCES bookings,rating SMALLINT NOT NULL CHECK(rating BETWEEN 1 AND 5),comment TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_log(audit_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,table_name TEXT NOT NULL,record_id BIGINT,action TEXT NOT NULL CHECK(action IN ('INSERT','UPDATE','DELETE')),old_data JSONB,new_data JSONB,changed_by BIGINT,changed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_vehicles_branch_status ON vehicles(branch_id,status); CREATE INDEX idx_vehicles_category ON vehicles(category_id); CREATE INDEX idx_bookings_customer ON bookings(customer_id,created_at DESC); CREATE INDEX idx_bookings_live ON bookings(vehicle_id) WHERE status IN ('confirmed','active'); CREATE INDEX idx_payments_booking ON payments(booking_id); CREATE INDEX idx_maintenance_vehicle ON maintenance_records(vehicle_id); CREATE INDEX idx_audit_table_record ON audit_log(table_name,record_id);
